// Carte du monde — Natural Earth 110m, projetée en Web-Mercator (base 1000×633.3),
// simplifiée et pré-projetée. project() partage EXACTEMENT le même repère que les
// tracés pays → les points visiteurs tombent au bon endroit. Antarctique retiré.
export const WORLD_W = 1000;
export const WORLD_H = 633.3;
const LAT_TOP = 83;
const W = 1000;
const clampLat = (l: number) => Math.max(-85, Math.min(85, l));
const mercY = (lat: number) => (0.5 - Math.log(Math.tan(Math.PI / 4 + (clampLat(lat) * Math.PI / 180) / 2)) / (2 * Math.PI)) * W;
const Y_TOP = mercY(LAT_TOP);
export function projectWorld(lng: number, lat: number): [number, number] {
  return [((lng + 180) / 360) * W, mercY(lat) - Y_TOP];
}
